INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(53778229, 'Silent Graveyard', '墓地封印', '墓地封印', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：丢弃1张手卡才能发动。这个回合，墓地发动的卡的效果无效化。'),
(40867519, 'Silent Insect', '静寂虫', '静寂虫', 'Effect Monster', 'Insect', 'EARTH', 2, 200, 300, '这张卡召唤·反转召唤成功的场合变成守备表示。只要这张卡在场上表侧表示存在，永续魔法·永续陷阱卡的效果无效。'),
(41175645, 'Silent Magician', '沉默魔术师', '沈黙の魔術師－サイレント・マジシャン', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1000, 1000, '这张卡不能通常召唤。把自己场上1只魔法师族怪兽解放的场合才能特殊召唤。 ①：这张卡的攻击力上升自己手卡数量×500。 ②：1回合1次，魔法卡发动时才能发动。那个发动无效。 ③：场上的这张卡被战斗或者对方的效果破坏的场合才能发动。从手卡·卡组把「沉默魔术师」以外的1只「沉默魔术师」怪兽无视召唤条件特殊召唤。'),
(73665146, 'Silent Magician LV4', '沉默魔术师 LV4', 'サイレント・マジシャン LV４', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1000, 1000, '①：只要这张卡在怪兽区域存在，每次对方抽卡，给这张卡放置1个魔力指示物（最多5个）。 ②：这张卡的攻击力上升这张卡的魔力指示物数量×500。 ③：这张卡有第5个魔力指示物被放置的下次的自己回合的准备阶段，把有5个魔力指示物放置的这张卡送去墓地才能发动。从手卡·卡组把1只「沉默魔术师 LV8」特殊召唤。'),
(72443568, 'Silent Magician LV8', '沉默魔术师 LV8', 'サイレント・マジシャン LV８', 'Effect Monster', 'Spellcaster', 'LIGHT', 8, 3500, 1000, '这张卡不能通常召唤，用「沉默魔术师 LV4」的效果才能特殊召唤。 ①：这张卡只要在怪兽区域存在，不受对方的魔法卡的效果影响。'),
(65726770, 'Silent Magician Zero', '沉默魔术师・零', 'サイレント・マジシャン・ゼロ', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1000, 1000, '这个卡名的③的效果1回合只能使用1次。 ①：对方抽卡的场合发动。这张卡的等级上升抽出数量的数值。 ②：这张卡的等级比原本等级高的场合，这张卡的攻击力上升那个相差数值×500。 ③：自己场上有「光之黄金柜」存在，对方把魔法卡的效果发动时才能发动。那个发动无效，这张卡的等级上升1星。'),
(19502505, 'Silent Paladin', '沉默魔导剑士', '沈黙の魔導剣士－サイレント・パラディン', 'Effect Monster', 'Fairy', 'LIGHT', 4, 500, 1500, '①：这张卡召唤成功时才能发动。从卡组把1只「沉默剑士 LV3」或者「沉默魔术师 LV4」加入手卡。 ②：只在这张卡在场上表侧表示存在才有1次，只以自己场上的怪兽1只为对象的魔法卡发动时才能发动。那个发动无效。 ③：场上的这张卡被战斗或者对方的效果破坏的场合，以自己墓地1只光属性「LV」怪兽为对象才能发动。那只怪兽加入手卡。'),
(16246535, 'Silent Psychic Magician', '沉默的念力魔术师', '沈黙のサイコマジシャン', 'Synchro Tuner Monster', 'Psychic', 'EARTH', 5, 2400, 500, '调整＋调整以外的怪兽1只以上 这个卡名的①的效果1回合只能使用1次。 ①：这张卡特殊召唤的场合，以自己的墓地·除外状态的1只4星以下的念动力族怪兽为对象才能发动。那只怪兽特殊召唤。那之后，可以让那只怪兽的等级上升1星。这个回合，自己不是念动力族怪兽不能从额外卡组特殊召唤。 ②：把自己场上的这张卡作为同调素材的场合，可以把这张卡当作调整以外的怪兽使用。'),
(62950604, 'Silent Psychic Wizard', '沉默的念力巫师', '沈黙のサイコウィザード', 'Effect Monster', 'Psychic', 'EARTH', 4, 1900, NULL, '这张卡召唤成功时，可以选择自己墓地存在的1只念动力族怪兽从游戏中除外。这张卡从场上送去墓地时，这张卡的效果除外的怪兽特殊召唤。'),
(31059809, 'Silent Sea Nettle', '寂静海刺', 'サイレンス・シーネットル', 'Effect Monster', 'Aqua', 'WATER', 4, 800, 1300, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有水属性怪兽存在的场合才能发动。这张卡从手卡特殊召唤。这个效果发动的回合，自己不是水属性怪兽不能特殊召唤。 ②：把墓地的这张卡除外，以自己墓地最多3只水属性怪兽为对象才能发动。那些怪兽回到卡组。'),
(18235577, 'Silent Strider', '寂寂虫', '寂々虫', 'Effect Monster', 'Insect', 'EARTH', 2, 300, 700, '把这张卡从手卡送去墓地发动。场上存在的1只怪兽的等级直到结束阶段时下降1星。'),
(18563744, 'Silent Sword Slash', '沉默之剑', '沈黙の剣', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以自己场上1只「沉默剑士」怪兽为对象才能发动（这张卡的发动和效果不会被无效化）。那只自己怪兽攻击力·守备力上升1500，直到回合结束时不受对方的效果影响。 ②：自己主要阶段把墓地的这张卡除外才能发动。从卡组把1只「沉默剑士」怪兽加入手卡。'),
(15180041, 'Silent Swordsman', '沉默剑士', '沈黙の剣士－サイレント・ソードマン', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1000, 1000, '这张卡不能通常召唤。把自己场上1只战士族怪兽解放的场合才能特殊召唤。 ①：自己·对方的准备阶段发动。这张卡的攻击力上升500。 ②：1回合1次，魔法卡发动时才能发动。那个发动无效。 ③：场上的这张卡被战斗或者对方的效果破坏的场合才能发动。从手卡·卡组把「沉默剑士」以外的1只「沉默剑士」怪兽无视召唤条件特殊召唤。'),
(1995985, 'Silent Swordsman LV3', '沉默剑士 LV3', 'サイレント・ソードマン LV３', 'Effect Monster', 'Warrior', 'LIGHT', 3, 1000, 1000, '①：只要这张卡在怪兽区域存在，这张卡为对象的对方的魔法卡的效果无效化。 ②：自己准备阶段把场上的这张卡送去墓地才能发动。从手卡·卡组把1只「沉默剑士 LV5」特殊召唤。这个效果在这张卡召唤·特殊召唤·反转的回合不能发动。'),
(74388798, 'Silent Swordsman LV5', '沉默剑士 LV5', 'サイレント・ソードマン LV５', 'Effect Monster', 'Warrior', 'LIGHT', 5, 2300, 1000, '①：这张卡不受对方的魔法卡的效果影响。 ②：这张卡直接攻击给与对方战斗伤害的场合，下次的自己回合的准备阶段把场上的这张卡送去墓地才能发动。从手卡·卡组把1只「沉默剑士 LV7」特殊召唤。'),
(37267041, 'Silent Swordsman LV7', '沉默剑士 LV7', 'サイレント・ソードマン LV７', 'Effect Monster', 'Warrior', 'LIGHT', 7, 2800, 1000, '这张卡不能通常召唤。「沉默剑士 LV5」的效果才能特殊召唤。 ①：只要这张卡在怪兽区域存在，场上的魔法卡的效果无效化。'),
(39321065, 'Silent Swordsman Zero', '沉默剑士・零', 'サイレント・ソードマン・ゼロ', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1000, 1000, '这个卡名的③的效果1回合只能使用1次。 ①：自己·对方的准备阶段发动。这张卡的等级上升1星。 ②：这张卡的等级比原本等级高的场合，这张卡的攻击力上升那个相差数值×500。 ③：以自己场上的「光之黄金柜」或者有那个卡名记述的怪兽为对象的效果由对方发动时才能发动。那个发动无效，这张卡的等级上升1星。'),
(71015787, 'Silent Wobby', '寂静须鲨', 'サイレント・ウォビー', 'Effect Monster', 'Fish', 'WATER', 4, 1000, 2000, '自己的主要阶段时才能发动。这张卡从手卡往对方场上特殊召唤。这个效果特殊召唤成功时，这张卡的控制者从卡组抽1张卡，从这张卡的控制者来看的对方玩家回复2000基本分。「寂静须鲨」的这个效果1回合只能使用1次。此外，只要这张卡在场上表侧表示存在，这张卡的控制者的手卡限制数量变成3张。'),
(15947754, 'Silent Wolf Calupo', '沉默狼-卡鲁波狼犬', '沈黙狼－カルーポ', 'Effect Monster', 'Beast-Warrior', 'DARK', 4, 1400, 1400, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的场合发动。自己卡组最上面的卡当作攻击力上升500的装备卡使用以里侧表示给这张卡装备。 ②：自己·对方的结束阶段发动。对方对这张卡的①的效果装备中的卡的原本种类（怪兽·魔法·陷阱）作猜测。猜中的场合，这张卡送去墓地。猜错的场合，对方手卡随机选1张丢弃，这张卡回到持有者手卡。'),
(1528054, 'Silhouhatte Rabbit', '影法师 高帽兔', '影法師トップハットヘア', 'Link Monster', 'Illusion', 'LIGHT', NULL, 1500, NULL, '效果怪兽2只 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡连接召唤的场合才能发动。把持有把自身作为怪兽特殊召唤效果的1张永续陷阱卡从卡组到自己场上盖放。这张卡在这个回合不能作为连接素材。 ②：这张卡和怪兽进行战斗的场合，那2只不会被那次战斗破坏。 ③：魔法与陷阱区域的卡在怪兽区域特殊召唤的场合，以对方场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。'),
(24440742, 'Silhouhatte Trick', '影帽子', '影帽子', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：这张卡发动后变成持有以下效果的效果怪兽（幻想魔族·暗·4星·攻1500/守600）在怪兽区域特殊召唤（也当作陷阱卡使用）。 ●这张卡特殊召唤的场合，以最多有自己场上的幻想魔族怪兽数量的对方场上的表侧表示卡为对象才能发动。那些卡的效果直到回合结束时无效。 ●这张卡和怪兽进行战斗的场合，那2只不会被那次战斗破坏。'),
(18300894, 'Silk Bomb Moth', '丝爆弹蛾', NULL, 'Effect Monster', 'Insect', 'WIND', 6, 2400, 1000, '自己墓地有2只以上风属性怪兽存在，这张卡在自己手卡存在的场合：可以把这张卡特殊召唤，自己墓地1只风属性怪兽加入卡组洗切。 这张卡召唤·特殊召唤的场合：可以把对方卡组最上面的卡给双方确认，根据那张卡的种类适用以下效果。 ●怪兽：那只怪兽当作永续魔法卡使用在对方的魔法与陷阱区域放置。 ●魔法·陷阱卡：那张卡除外。 「丝爆弹蛾」的每个效果1回合各能使用1次。'),
(32619583, 'Sillva, Warlord of Dark World', '暗黑界的军神 希尔瓦', '暗黒界の軍神 シルバ', 'Effect Monster', 'Fiend', 'DARK', 5, 2300, 1400, '①：这张卡被效果从手卡丢弃去墓地的场合发动。这张卡特殊召唤。被对方的效果丢弃的场合，再让对方选自身2张手卡用喜欢的顺序回到卡组下面。'),
(73001017, 'Silpheed', '希尔菲德', 'シルフィード', 'Effect Monster', 'Fairy', 'WIND', 4, 1700, 700, '这张卡不能进行通常召唤。从自己墓地里除外1只风属性怪兽进行特殊召唤。这张卡被战斗破坏送去墓地时，对方随机丢弃1张手卡。'),
(1557499, 'Silver Bow and Arrow', '银之弓矢', '銀の弓矢', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '天使族才能装备。1只装备怪兽的攻击力·守备力上升300。'),
(90357090, 'Silver Fang', '银牙', 'シルバー・フォング', 'Normal Monster', 'Beast', 'EARTH', 3, 1200, 800, '银光闪闪的狼。外表虽然美，性格却凶暴。'),
(29021114, 'Silver Gadget', '银色小工具', 'シルバー・ガジェット', 'Effect Monster', 'Machine', 'LIGHT', 4, 1500, 1000, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡召唤·特殊召唤成功时才能发动。从手卡把1只机械族·4星怪兽特殊召唤。 ②：这张卡被战斗·效果破坏的场合才能发动。从卡组把「银色零件」以外的1只4星「零件」怪兽特殊召唤。'),
(9791914, 'Silver Sentinel', '白银之狙击手', '白銀のスナイパー', 'Effect Monster', 'Warrior', 'EARTH', 4, 1500, 1300, '这张卡可以当作魔法卡使用从手卡到魔法与陷阱卡区域盖放。魔法与陷阱卡区域盖放的这张卡被对方的卡的效果破坏送去墓地的回合的结束阶段时，这张卡从墓地特殊召唤，选择对方场上1张卡破坏。'),
(25231813, 'Silver Wing', '白银之翼', '白銀の翼', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '8星以上的龙族同调怪兽才能装备。装备怪兽1回合最多2次不会被战斗破坏。装备怪兽被卡的效果破坏的场合，可以作为代替把这张卡破坏。'),
(87025064, 'Silver''s Cry', '银龙的轰咆', '銀龍の轟咆', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己墓地1只龙族通常怪兽为对象才能发动。那只龙族怪兽特殊召唤。'),
(41924516, 'Silvera, Wolf Tamer of the White Forest', '白森的魔狼 西尔维亚', '白き森の魔狼シルウィア', 'Synchro Tuner Monster', 'Spellcaster', 'LIGHT', 6, 1900, 2400, '调整＋调整以外的怪兽1只以上 ①：这张卡特殊召唤的场合才能发动。对方场上的表侧表示怪兽全部变成里侧守备表示。 ②：只要这张卡在怪兽区域存在，自己场上的幻想魔族·魔法师族的同调怪兽攻击力上升500，向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的2倍数值的战斗伤害。'),
(32476603, 'Silverrokket Dragon', '银色枪弹龙', 'シルバーヴァレット・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 4, 1900, 100, '这个卡名的①②的效果1回合各能使用1次。 ①：场上的这张卡为对象的连接怪兽的效果发动时才能发动。这张卡破坏。那之后，把对方的额外卡组确认，那之内的1张除外。 ②：场上的这张卡被战斗·效果破坏送去墓地的回合的结束阶段才能发动。从卡组把「银色弹丸龙」以外的1只「弹丸」怪兽特殊召唤。'),
(13382806, 'Silvervine Senri', '木天蓼仙狸', 'マタタビ仙狸', 'Effect Monster', 'Beast', 'WIND', 2, NULL, NULL, '这个卡名的效果1回合只能使用1次。 ①：把这张卡解放，以「木天蓼仙狸」以外的自己墓地1只2星怪兽为对象才能发动。那只怪兽特殊召唤。那之后，可以把和这个效果特殊召唤的怪兽属性不同的1只2星怪兽从手卡特殊召唤。'),
(98385955, 'Silvy of the White Forest', '白森的西尔薇', '白き森のシルヴィ', 'Tuner Monster', 'Spellcaster', 'LIGHT', 4, 1500, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把1张「白森林」魔法·陷阱卡加入手卡。 ②：自己·对方回合，这张卡在墓地存在的场合，以自己的场上·墓地1只「白森林」同调怪兽为对象才能发动。那只怪兽回到额外卡组，这张卡效果无效特殊召唤。'),
(67218327, 'SIMM Tablir', '单列内存模块貘', 'SIMMタブラス', 'Effect Monster', 'Cyberse', 'DARK', 5, NULL, 1800, '这个卡名的效果1回合只能使用1次。 ①：把手卡的这张卡给对方观看，以自己墓地1只电子界族·4星怪兽为对象才能发动。这张卡从手卡往作为连接状态的自己的连接怪兽的所连接区的自己场上特殊召唤，作为对象的怪兽回到手卡。'),
(22586618, 'Simorgh of Darkness', '黑暗冥西摩格', 'ダークネス・シムルグ', 'Effect Monster', 'Winged Beast', 'DARK', 8, 2900, 2000, '这个卡名的①③的效果1回合各能使用1次。 ①：这张卡在手卡·墓地存在，自己对暗属性或者风属性的怪兽的上级召唤成功的场合才能发动。这张卡特殊召唤。 ②：只要这张卡在怪兽区域存在，这张卡的属性也当作「风」使用。 ③：魔法·陷阱卡的效果发动时，把自己场上1只鸟兽族·风属性怪兽解放才能发动。那个发动无效并破坏。'),
(28617139, 'Simorgh Onslaught', '西摩格之来寇', '神鳥の来寇', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从手卡丢弃1只鸟兽族怪兽才能发动。从卡组把2只「斯摩夫」怪兽加入手卡（相同属性最多1只）。 ②：把墓地的这张卡除外才能发动。手卡1只鸟兽族怪兽给对方观看。这个回合，那只怪兽以及自己手卡的同名怪兽的等级下降1星。'),
(64002884, 'Simorgh Repulsion', '西摩格之排击', '神鳥の排撃', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从手卡丢弃1只鸟兽族怪兽才能发动。对方的魔法与陷阱区域的卡全部回到持有者手卡。 ②：把墓地的这张卡除外才能发动。手卡1只鸟兽族怪兽给对方观看。这个回合，那只怪兽以及自己手卡的同名怪兽的等级下降1星。'),
(57823578, 'Simorgh Sky Battle', '西摩格之烈战', '神鳥の烈戦', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上的鸟兽族怪兽之内除攻击力最高的鸟兽族怪兽以外的鸟兽族怪兽不会成为攻击对象，也不会成为对方的效果的对象。 ②：把自己场上2只原本等级是7星以上而原本属性不同的「斯摩夫」怪兽和这张卡送去墓地才能发动。场上的卡全部回到持有者手卡，自己受到回到手卡的数量×500伤害。那之后，给与对方为和自己受到的伤害相同数值的伤害。'),
(86489182, 'Simorgh, Bird of Ancestry', '始祖神鸟 斯摩夫', '始祖神鳥シムルグ', 'Effect Monster', 'Winged Beast', 'WIND', 8, 2900, 2000, '这张卡在手卡的场合，当作通常怪兽使用。只要这张卡在场上表侧表示存在，风属性怪兽的祭品召唤需要的祭品变少1只。只用风属性怪兽作为祭品对这张卡的祭品召唤成功时，对方场上最多2张卡回到持有者手卡。'),
(50820852, 'Simorgh, Bird of Beginning', '雏神鸟 西摩格', '雛神鳥シムルグ', 'Effect Monster', 'Winged Beast', 'WIND', 1, NULL, 1600, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤成功时才能发动。这个回合，自己在通常召唤外加上只有1次，自己主要阶段可以把1只「斯摩夫」怪兽召唤。 ②：这张卡在墓地存在，对方的魔法与陷阱区域没有卡存在的场合才能发动。这张卡守备表示特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。这个效果的发动后，直到回合结束时自己不是鸟兽族怪兽不能特殊召唤。'),
(96214561, 'Simorgh, Bird of Bringing', '招神鸟 西摩格', '招神鳥シムルグ', 'Effect Monster', 'Winged Beast', 'WIND', 2, 1000, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤成功时才能发动。从卡组把「招神鸟 斯摩夫」以外的1张「斯摩夫」卡加入手卡。 ②：这张卡在墓地存在，对方的魔法与陷阱区域没有卡存在的场合才能发动。这张卡守备表示特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。这个效果的发动后，直到回合结束时自己不是鸟兽族怪兽不能特殊召唤。'),
(23619206, 'Simorgh, Bird of Calamity', '死神鸟 西摩格', '死神鳥シムルグ', 'Effect Monster', 'Winged Beast', 'WIND', 3, 1500, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤成功时才能发动。从卡组把「死神鸟 斯摩夫」以外的1张「斯摩夫」卡送去墓地。 ②：这张卡在墓地存在，对方的魔法与陷阱区域没有卡存在的场合才能发动。这张卡守备表示特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。这个效果的发动后，直到回合结束时自己不是鸟兽族怪兽不能特殊召唤。'),
(14989021, 'Simorgh, Bird of Divinity', '神鸟 斯摩夫', '神鳥シムルグ', 'Effect Monster', 'Winged Beast', 'WIND', 7, 2700, 1000, '这张卡不能特殊召唤。这张卡上级召唤的场合，解放的怪兽必须是风属性怪兽。只要这张卡在场上表侧表示存在，双方玩家在每次双方的结束阶段受到1000分伤害。这个时候，各自玩家受到的伤害变少魔法·陷阱卡控制数量×500的数值。'),
(52843699, 'Simorgh, Bird of Perfection', '绝神鸟 西摩格', '絶神鳥シムルグ', 'Effect Monster', 'Winged Beast', 'DARK', 4, 1800, 500, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段，自己对鸟兽族怪兽的召唤·特殊召唤成功的场合，把手卡的这张卡给对方观看才能发动。把1只「斯摩夫」怪兽召唤。 ②：这张卡召唤成功的场合，从卡组把1只「斯摩夫」怪兽送去墓地才能发动。从卡组把1张「斯摩夫」魔法·陷阱卡加入手卡。 ③：只要这张卡在怪兽区域存在，这张卡的属性也当作「风」使用。'),
(59707204, 'Simorgh, Bird of Protection', '护神鸟 西摩格', '護神鳥シムルグ', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1400, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤成功时，以对方的魔法与陷阱区域1张卡为对象才能发动。那张卡回到持有者手卡。 ②：这张卡在墓地存在，对方的魔法与陷阱区域没有卡存在的场合才能发动。这张卡守备表示特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。这个效果的发动后，直到回合结束时自己不是鸟兽族怪兽不能特殊召唤。'),
(72330894, 'Simorgh, Bird of Sovereignty', '王神鸟 西摩格', '王神鳥シムルグ', 'Link Monster', 'Winged Beast', 'WIND', NULL, 2400, NULL, '包含鸟兽族怪兽的怪兽2只以上 这个卡名的③的效果1回合只能使用1次。这张卡不能作为连接素材。 ①：这张卡以及这张卡所连接区的鸟兽族怪兽不会成为对方的效果的对象。 ②：这张卡被战斗破坏的场合，可以作为代替把自己场上1张「斯摩夫」卡破坏。 ③：自己·对方的结束阶段才能发动。把持有没有使用的自己·对方的魔法与陷阱区域数量以下的等级的1只鸟兽族怪兽从手卡·卡组特殊召唤。'),
(95192919, 'Simorgh, Lord of the Storm', '烈风霸者 西摩格', '烈風の覇者シムルグ', 'Effect Monster', 'Winged Beast', 'WIND', 8, 2900, 2000, '这个卡名的②③的效果1回合各能使用1次。 ①：上级召唤的这张卡不会成为对方的魔法·陷阱卡的效果的对象。 ②：魔法·陷阱卡的效果发动时，把自己场上1只鸟兽族·风属性怪兽解放，以对方场上1张卡为对象才能发动。那张卡回到持有者卡组。 ③：这张卡在墓地存在，自己的鸟兽族怪兽被战斗破坏时才能发动。这张卡加入手卡。'),
(94423983, 'Simul Archfiends', '同契恶魔术', '同契魔術', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：这个回合，双方不能把和自身场上的怪兽相同种类（仪式·融合·同调·超量·连接）的怪兽特殊召唤。自己场上是仪式·融合·同调·超量·连接怪兽的其中每种都没有2只以上存在的场合，自己场上的全部仪式·融合·同调·超量·连接怪兽的攻击力上升500。'),
(25096909, 'Simultaneous Equation Cannons', '连栗炮固定式', '連慄砲固定式', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：等级·阶级的合计直到变成和双方的手卡·场上的卡数量相同为止，从自己的额外卡组把2只超量怪兽（相同阶级）和1只融合怪兽除外。那之后，以下效果可以适用。 ●选对方场上1只表侧表示怪兽，等级·阶级的合计直到变成和那只怪兽的等级·阶级相同为止让自己的除外状态的1只超量怪兽和1只融合怪兽回到额外卡组。那之后，对方场上的卡全部除外。'),
(92219931, 'Simultaneous Loss', '二者一两损', '二者一両損', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '双方互相把自己卡组最上面的1张卡送去墓地。'),
(2006591, 'Sinful Spoils Awakening', '觉醒的罪宝', '目醒める罪宝', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己场上有5星以上的幻想魔族怪兽存在，对方场上有怪兽3只以上存在的场合，以对方场上最多3张卡为对象才能发动。那些卡回到手卡。 ②：这张卡在墓地存在，自己场上有5星以上的幻想魔族怪兽存在的场合才能发动。这张卡在自己场上盖放。这个效果盖放的这张卡从场上离开的场合除外。'),
(38511382, 'Sinful Spoils of Betrayal - Silvera', '背叛之罪宝－西尔维亚', '裏切りの罪宝－シルウィア', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从自己的手卡·场上（表侧表示）把1只「迪亚贝尔斯塔尔」怪兽送去墓地，以场上1张表侧表示卡为对象才能发动。那张卡的效果无效。 ②：对方连锁自己的「迪亚贝尔斯塔尔」怪兽或者自己的「罪宝」魔法·陷阱卡的效果的发动把魔法·陷阱·怪兽的效果发动时，把墓地的这张卡除外才能发动。那个对方的效果无效。'),
(16240772, 'Sinful Spoils of Doom - Rciela', '死之罪宝－露西耶拉', '死の罪宝－ルシエラ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只7星以上的魔法师族怪兽为对象才能发动。以下效果各适用。 ●作为对象的表侧表示怪兽在这个回合不受其他怪兽的效果影响，下个回合的准备阶段送去墓地。 ●对方场上的全部怪兽的攻击力下降作为对象的怪兽的攻击力数值。这个效果让攻击力变成0的场合，再把那怪兽破坏。'),
(53329234, 'Sinful Spoils of Slumber - Morrian', '微睡之罪宝－摩莉安', '微睡の罪宝－モーリアン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以场上1只特殊召唤的表侧表示怪兽为对象才能发动。那只怪兽变成里侧守备表示。 ②：这张卡在墓地存在，自己场上有5星以上的幻想魔族怪兽存在的场合才能发动。这张卡在自己场上盖放。这个效果盖放的这张卡从场上离开的场合除外。'),
(24081957, 'Sinful Spoils of Subversion - Snake-Eye', '反逆之罪宝－蛇眼', '反逆の罪宝－スネークアイ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以场上1只表侧表示怪兽为对象才能发动。那只怪兽当作永续魔法卡使用在原本持有者的魔法与陷阱区域表侧表示放置。'),
(3496543, 'Sinful Spoils of the White Forest', '白森之罪宝', '白き森の罪宝', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有恶魔族·幻想魔族·魔法师族怪兽的其中任意种存在的场合，可以从以下效果选择1个发动。 ●从手卡把1只恶魔族·幻想魔族·魔法师族怪兽特殊召唤。 ●自己的手卡·场上的怪兽作为融合素材，把1只融合怪兽融合召唤。 ②：这张卡为让怪兽的效果发动而被送去墓地的场合才能发动。这张卡在自己场上盖放。'),
(90386276, 'Sinful Spoils Sanctification', '无罪的罪宝', '罪なき罪宝', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：可以从以下效果选择1个发动。 ●以自己的墓地·除外状态的1只「迪亚贝尔」怪兽为对象才能发动。选自己1张手卡丢弃，作为对象的怪兽特殊召唤。 ●以自己的魔法与陷阱区域1张表侧表示的怪兽卡为对象才能发动。那张卡特殊召唤。'),
(67457739, 'Sinful Spoils Struggle', '罪宝合战', '罪宝合戦', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以场上的卡任意数量为对象才能发动（自己场上的卡是以最多有自己的墓地·除外状态的「罪宝」卡数量，对方场上的卡是以最多有对方的墓地·除外状态的「罪宝」卡数量）。那些卡破坏。 ②：盖放的这张卡被对方的所发动的效果所破坏的场合或者所除外的场合才能发动。场上最多2张卡回到卡组。'),
(26334139, 'Sinful Spoils Subdual', '峰回罪宝', '廻る罪宝', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从卡组选1只5星以上的幻想魔族怪兽加入手卡或特殊召唤。这个回合的主要阶段内，自己不能把这个效果特殊召唤的怪兽的效果发动。 ②：把墓地的这张卡除外，以自己场上1张里侧表示卡为对象才能发动。那张卡回到手卡。那之后，可以从手卡把1张魔法·陷阱卡盖放。'),
(68661341, 'Single Purchase', '一点式买法', '一点買い', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡以外的手卡有3张以上存在，那之中没有怪兽卡存在的场合，把手卡全部表侧表示从游戏中除外才能发动。从卡组把1只怪兽加入手卡。这个回合，自己不能把加入手卡的同名怪兽以外的怪兽召唤·特殊召唤。'),
(32484853, 'Singularity Fiend', '特异点恶魔', '特異点の悪魔', 'Effect Monster', 'Fiend', 'DARK', 1, NULL, NULL, '这个卡名的效果1回合只能使用1次。 ①：对方把怪兽特殊召唤时，从手卡把这张卡和1张魔法卡丢弃才能发动。那些怪兽破坏。'),
(60406592, 'Sinister Seed Token', '魔界凤仙花种', 'デモンバルサム・シード', 'Token', 'Plant', NULL, NULL, NULL, NULL, NULL),
(60406591, 'Sinister Seeds', '魔界凤仙花种', 'デモンバルサム・シード', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上表侧攻击表示存在的怪兽被战斗破坏时才能发动。那次战斗让自己受到的战斗伤害每有500分，在自己场上把1只「魔界凤仙花衍生物」（植物族·暗·1星·攻/守100）特殊召唤。'),
(8131171, 'Sinister Serpent', '杀人蛇', 'キラー・スネーク', 'Effect Monster', 'Reptile', 'WATER', 1, 300, 250, '「杀人蛇」的效果1回合只能使用1次。 ①：这张卡在墓地存在的场合，自己准备阶段才能发动。这张卡回到手卡。下次的对方结束阶段选自己墓地1只「杀人蛇」除外。'),
(77505534, 'Sinister Shadow Games', '坠影的蠢动', '堕ち影の蠢き', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：从卡组把1张「影依」卡送去墓地。那之后，可以选自己场上的里侧守备表示的「影依」怪兽任意数量变成表侧守备表示。'),
(61632317, 'Sinister Sprocket', '暗黑链齿怪', 'ダーク・スプロケッター', 'Tuner Monster', 'Fiend', 'DARK', 1, 400, NULL, '这张卡被暗属性的同调怪兽的同调召唤使用送去墓地的场合，可以把场上表侧表示存在的1张魔法或者陷阱卡破坏。'),
(72497366, 'Sinister Yorishiro', '魔鬼的附体', '悪魔の憑代', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，自己在5星以上的恶魔族怪兽召唤的场合需要的解放可以不用。这个效果1回合只能适用1次。 ②：只让通常召唤的5星以上的恶魔族怪兽1只被破坏的场合，可以作为代替把这张卡送去墓地。'),
(70391589, 'Siphon Token', '星食-等级攀升-', '星蝕－レベル・クライム－', 'Token', 'Spellcaster', NULL, NULL, NULL, NULL, NULL),
(50074392, 'Sirenorca', '灵水鸟 鲸鸟海妖', '霊水鳥シレーヌ・オルカ', 'Effect Monster', 'Winged Beast', 'WATER', 5, 2200, 1000, '自己场上有鱼族以及鸟兽族怪兽存在的场合，这张卡可以从手卡特殊召唤。这个方法特殊召唤成功时，宣言从3到5的任意等级才能发动。自己场上的全部怪兽的等级变成宣言的等级。这个效果发动过的回合，水属性以外的自己怪兽不能把效果发动。'),
(57019473, 'Sishunder', '雷电姐姐', 'ONeサンダー', 'Effect Monster', 'Thunder', 'LIGHT', 4, 900, 400, '这张卡召唤成功时，可以选择「雷电姐姐」以外的自己墓地1只雷族·光属性·4星·攻击力1600以下的怪兽从游戏中除外。这个回合的结束阶段时那张卡加入手卡。'),
(72345736, 'Six Samurai United', '六武众之团结', '六武衆の結束', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：每次「六武众」怪兽召唤·特殊召唤给这张卡放置1个武士道指示物（最多2个）。 ②：把有武士道指示物放置的这张卡送去墓地才能发动。自己从卡组抽出这张卡放置的武士道指示物的数量。'),
(54913680, 'Six Scrolls of the Samurai', '六武之书', '六武ノ書', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '把自己场上表侧表示存在的2只名字带有「六武众」的怪兽解放发动。从自己卡组把1只「大将军 紫炎」在自己场上特殊召唤。'),
(28273805, 'Six Strike - Double Assault', '六武式袭双阵', '六武式襲双陣', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从以下效果选1个适用。自己场上有「六武众」怪兽2只以上存在的场合，可以选两方适用。 ●从自己的手卡·墓地把1只攻击力2000以下的「六武众」怪兽特殊召唤。 ●对方场上1只攻击力2000以下的怪兽变成里侧守备表示。 ②：自己主要阶段把墓地的这张卡除外，以自己墓地1只「六武众」怪兽为对象才能发动。那只怪兽加入手卡。'),
(90939874, 'Six Strike - Sextuple Barrage', '六武式真传天魔六段冲', '六武式真伝天魔六段衝', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「六武众」同调怪兽3种类以上存在的场合才能发动（为这张卡发动而需要的怪兽种类改成自己场上的武士道指示物每有6个则少要1种类的数量）。对方场上的卡全部破坏。 ②：盖放的这张卡被对方的所发动的效果所破坏的场合或者所除外的场合才能发动。从卡组·额外卡组把1只「六武众」怪兽或「紫炎」效果怪兽特殊召唤。'),
(23212990, 'Six Strike - Thunder Blast', '六武式风雷斩', '六武式風雷斬', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上的1个武士道指示物取除，从以下效果选择1个发动。 ●选择对方场上存在的1只怪兽破坏。 ●选择对方场上存在的1张卡回到手卡。'),
(81426505, 'Six Strike - Triple Impact', '六武式三段冲', '六武式三段衝', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有名字带有「六武众」的怪兽表侧表示3只以上存在的场合，可以从以下效果选择1个发动。 ●对方场上表侧表示存在的怪兽全部破坏。 ●对方场上表侧表示存在的魔法·陷阱卡全部破坏。 ●对方场上盖放的魔法·陷阱卡全部破坏。'),
(75525309, 'Six Style - Dual Wield', '六武派二刀流', '六武派二刀流', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上存在的怪兽只有表侧攻击表示存在的名字带有「六武众」的怪兽1只的场合才能发动。选择对方场上存在的2张卡回到持有者手卡。'),
(3280747, 'Sixth Sense', '第六感', '第六感', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己在1至6的范围里宣言2个数字。对方丢出1个「骰子」，丢出的数目是宣言的数字的其中1个，自己就抽相等数目的卡。猜不中的场合，自己卡组从上面丢弃「骰子」丢出数目的卡去墓地。'),
(60694662, 'Skelengel', '骸骨天使', 'スケルエンジェル', 'Flip Effect Monster', 'Fairy', 'LIGHT', 2, 900, 400, '①：这张卡反转的场合发动。自己从卡组抽1张。'),
(89362180, 'Skelesaurus', '天生的白骨恐龙', 'ナチュラル・ボーン・サウルス', 'Gemini Monster', 'Zombie', 'DARK', 4, 1700, 1400, '①：这张卡只要在场上·墓地存在，当作通常怪兽使用。 ②：可以把场上的当作通常怪兽使用的这张卡作为通常召唤作再1次召唤。那个场合这张卡变成当作效果怪兽使用并得到以下效果。 ●这张卡的种族·属性变成恐龙族·地属性。 ●这张卡战斗破坏对方怪兽送去墓地时才能发动。那只怪兽在自己场上守备表示特殊召唤。这个效果特殊召唤的怪兽的种族变成不死族。'),
(65187687, 'Skeletal Dragon Felgrand', '巨骸龙 绯尔格兰特', '巨骸竜フェルグラント', 'Synchro Monster', 'Zombie', 'LIGHT', 8, 2800, 2800, '不死族调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤成功的场合，以对方的场上·墓地1只怪兽为对象才能发动。那只怪兽除外。 ②：这张卡已在怪兽区域存在的状态，从墓地有怪兽特殊召唤的场合，以这张卡以外的场上1只表侧表示怪兽为对象才能发动。那只怪兽的效果直到回合结束时无效。'),
(32355828, 'Skelgon', '骸骨龙', 'スケルゴン', 'Fusion Monster', 'Zombie', 'DARK', 6, 1700, 1900, '「美杜莎的亡灵」＋「暗黑之龙王」'),
(82732705, 'Skill Drain', '技能抽取', 'スキルドレイン', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '支付1000基本分才能把这张卡发动。 ①：只要这张卡在魔法与陷阱区域存在，场上的表侧表示怪兽的效果无效化。'),
(63227401, 'Skill Prisoner', '技能禁锢', 'スキル・プリズナー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上1张卡才能发动。这个回合，选择的卡为对象发动的怪兽效果无效。此外，把墓地的这张卡从游戏中除外，选择自己场上1张卡才能发动。这个回合，选择的卡为对象发动的怪兽效果无效。这个效果在这张卡送去墓地的回合不能发动。'),
(73729209, 'Skill Successor', '技能继承', 'スキル・サクセサー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只怪兽发动。直到这个回合的结束阶段时，选择怪兽的攻击力上升400。此外，可以把墓地存在的这张卡从游戏中除外，自己场上表侧表示存在的1只怪兽的攻击力直到这个回合的结束阶段时上升800。这个效果在这张卡送去墓地的回合不能发动，自己回合才能发动。'),
(88901771, 'Skilled Blue Magician', '熟练的青魔道士', '熟練の青魔道士', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1800, 1800, '①：只要这张卡在怪兽区域存在，每次自己或者对方把魔法卡发动，给这张卡放置1个魔力指示物（最多3个）。 ②：把有3个魔力指示物放置的这张卡解放才能发动。从自己的手卡·卡组·墓地选1只「暗黑骑士 盖亚」怪兽特殊召唤。 ③：自己主要阶段把墓地的这张卡除外，以自己场上1张可以放置魔力指示物的卡为对象才能发动。给那张卡放置1个魔力指示物。'),
(88232397, 'Skilled Brown Magician', '熟练的栗魔导士', '熟練の栗魔導士', 'Effect Monster', 'Spellcaster', 'DARK', 4, 300, 200, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，每次自己或者对方把魔法卡发动，给这张卡放置1个魔力指示物（最多3个）。 ②：可以把这张卡1个魔力指示物取除，从以下效果选择1个发动。 ●这张卡的等级上升1星，攻击力上升1500。 ●从自己的卡组·墓地选1只「栗子球」怪兽或者1张「增殖」加入手卡。'),
(73752131, 'Skilled Dark Magician', '熟练的黑魔术师', '熟練の黒魔術師', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1900, 1700, '①：只要这张卡在怪兽区域存在，每次自己或者对方把魔法卡发动，给这张卡放置1个魔力指示物（最多3个）。 ②：把有3个魔力指示物放置的这张卡解放才能发动。从自己的手卡·卡组·墓地选1只「黑魔术师」特殊召唤。'),
(65338781, 'Skilled Red Magician', '熟练的赤魔术士', '熟練の赤魔術士', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1600, 1600, '①：只要这张卡在怪兽区域存在，每次自己或者对方把魔法卡发动，给这张卡放置1个魔力指示物（最多3个）。 ②：把有3个魔力指示物放置的这张卡解放才能发动。从自己的手卡·卡组·墓地选1只「恶魔」怪兽特殊召唤。 ③：自己主要阶段把墓地的这张卡除外，以自己场上1张可以放置魔力指示物的卡为对象才能发动。给那张卡放置1个魔力指示物。'),
(46363422, 'Skilled White Magician', '熟练的白魔导师', '熟練の白魔導師', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1700, 1900, '只要这张卡在场上表侧表示存在，每次自己或者对方把魔法卡发动，给这张卡放置1个魔力指示物（最多3个）。此外，把有3个魔力指示物放置的这张卡解放才能发动。从自己的手卡·卡组·墓地选1只「破坏之剑士」特殊召唤。'),
(27655513, 'Skreech', '尖叫怪', 'スクリーチ', 'Effect Monster', 'Reptile', 'WATER', 4, 1500, 400, '这张卡被战斗破坏的场合，从自己卡组选择2只水属性怪兽送去墓地。'),
(61370518, 'Skull Archfiend of Lightning', '迅雷之魔王-骸骨恶魔', '迅雷の魔王－スカル・デーモン', 'Effect Monster', 'Fiend', 'DARK', 6, 2500, 1200, '这张卡的控制者在自己的每1个准备阶段支付500基本分。当这张卡成为对方所控制的卡的效果对象时，在效果处理时掷1次骰子，若掷出1·3·6，则使此效果无效并将其破坏。'),
(62782218, 'Skull Conductor', '骷髅指挥', 'スカル・コンダクター', 'Effect Monster', 'Zombie', 'DARK', 4, 2000, NULL, '①：把这张卡从手卡送去墓地才能发动。攻击力合计直到变成2000为止选手卡最多2只不死族怪兽，那些怪兽特殊召唤。 ②：自己·对方的战斗阶段结束时发动。场上的表侧表示的这张卡破坏。'),
(126218, 'Skull Dice', '恶魔的骰子', '悪魔のサイコロ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：掷1次骰子。对方场上的怪兽的攻击力·守备力直到回合结束时下降出现的数目×100。'),
(86652646, 'Skull Dog Marron', '骨犬玛隆', '骨犬マロン', 'Normal Monster', 'Beast', 'EARTH', 4, 1350, 2000, '1000年前与主人不幸走散的迷犬。至今仍在等待着主人能够回来。'),
(99899504, 'Skull Flame', '骷髅炎鬼', 'スカル・フレイム', 'Effect Monster', 'Zombie', 'FIRE', 8, 2600, 2000, '1回合1次，可以从手卡把1只「燃烧骷髅头」特殊召唤。这个效果发动的回合，自己不能进行战斗阶段。此外，可以作为自己的抽卡阶段时进行通常抽卡的代替，把自己墓地存在的1只「燃烧骷髅头」加入手卡。'),
(3627449, 'Skull Guardian', '律守护者', 'ローガーディアン', 'Ritual Monster', 'Warrior', 'LIGHT', 7, 2050, 2500, '借由「法理的祈祷」降临。必须从场上或者手札，牺牲奉献等级合计为7个以上的卡。'),
(10774240, 'Skull Guardian, Protector of the Voiceless Voice', '肃声保卫者 律守护者', '粛声なる守護者ローガーディアン', 'Ritual Effect Monster', 'Warrior', 'LIGHT', 7, 2050, 2500, '「肃声之祈祷」降临 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡仪式召唤的场合才能发动。从卡组把1只「肃声」怪兽或者战士族·龙族的仪式怪兽加入手卡。 ②：只要自己的场上或墓地有「肃声的祈祷者 理」存在，这张卡的攻击力上升2050。 ③：自己场上有「肃声的祈祷者 理」存在，对方把魔法·陷阱·怪兽的效果发动时才能发动。那个发动无效并破坏。'),
(98139712, 'Skull Invitation', '死灵的引诱', '死霊の誘い', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '每次送卡去墓地，每1张卡、那些卡的主人基本分受到300的伤害。'),
(2504891, 'Skull Knight', '骷髅祭司', 'スカルビショップ', 'Fusion Monster', 'Spellcaster', 'DARK', 7, 2650, 2250, '「恶魔的智慧」＋「魔天老」'),
(15653824, 'Skull Knight #2', '骷髅骑士', 'スカル・ナイト', 'Effect Monster', 'Fiend', 'DARK', 3, 1000, 1200, '用这张卡做祭品召唤恶魔族怪兽的场合，从卡组特殊召唤1张「骷髅骑士」上场。之后卡组洗切。'),
(98649372, 'Skull Kraken', '骷髅章鱼', 'スカル・クラーケン', 'Effect Monster', 'Aqua', 'DARK', 3, 600, 1600, '这张卡召唤成功时，可以选择对方场上表侧表示存在的1张魔法卡破坏。1回合1次，可以把这张卡的表示形式变更。'),
(6733059, 'Skull Lair', '死灵之巢', '死霊の巣', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '除外自己的墓地存在的任意数目的怪兽，破坏1只场上的和这个数目相同等级的表侧表示的怪兽。'),
(5265750, 'Skull Mariner', '海贼船 血骸骨号', '海賊船スカルブラッド号', 'Normal Monster', 'Warrior', 'WATER', 4, 1600, 900, '船头仿照红色骸骨的海盗船。在所有海域神出鬼没地出现，袭击客船和货船。'),
(67750322, 'Skull Meister', '骷髅大师', 'スカル・マイスター', 'Effect Monster', 'Fiend', 'DARK', 4, 1700, 400, '①：对方墓地有魔法·陷阱·怪兽的效果发动时，把这张卡从手卡送去墓地才能发动。那个效果无效。'),
(10202894, 'Skull Red Bird', '天空猎手', 'スカイ・ハンター', 'Normal Monster', 'Winged Beast', 'WIND', 4, 1550, 1200, '在羽毛里藏着小刀，从空中降下发起攻击。'),
(32274490, 'Skull Servant', '白骨', 'ワイト', 'Normal Monster', 'Zombie', 'DARK', 1, 300, 200, '任何地方都会出现的骸骨怪。攻击很弱但聚集起来非同小可。'),
(54844990, 'Skull Stalker', '死亡潜行者', 'デス・ストーカー', 'Normal Monster', 'Warrior', 'DARK', 3, 900, 800, '行动敏捷、用钳子捕捉对方，带有剧毒刺针的蝎子战士。'),
(64306248, 'Skull-Mark Ladybug', '骷髅颜瓢虫', '髑髏顔 天道虫', 'Effect Monster', 'Insect', 'EARTH', 4, 500, 1500, '当这张卡被送去墓地时，自己回复1000基本分。'),
(8327462, 'Skullbird', '死亡鸟', 'デス・バード', 'Fusion Monster', 'Winged Beast', 'WIND', 6, 1900, 1700, '「橐蜚」＋「骷髅寺院」'),
(36776089, 'Sky Cavalry Centaurea', '神骑 圣人马', '神騎セイントレア', 'XYZ Monster', 'Beast-Warrior', 'LIGHT', 2, 2000, NULL, '2星怪兽×2 ①：持有超量素材的这张卡不会被战斗破坏。 ②：这张卡和对方怪兽进行战斗的伤害步骤结束时，把这张卡1个超量素材取除才能发动。那只对方怪兽回到手卡。'),
(95288024, 'Sky Dragon', '天空龙', '天空竜', 'Normal Monster', 'Dragon', 'WIND', 6, 1900, 1800, '有着四枚羽翼的鸟的外形的龙，用如刀刃一般的羽毛进行攻击。'),
(68182934, 'Sky Dragoons of Draconia', '多拉科尼亚的翼龙骑兵', 'ドラコニアの翼竜騎兵', 'Pendulum Normal Monster', 'Winged Beast', 'WIND', 5, 2200, 200, '龙人族国家德拉科尼亚帝国所拥有的龙骑士团空兵部队。有传闻说是为了对空中都市国家苏鲁伯这个中立国进行入侵而结成，使得周边国家对此加强警戒。'),
(2519690, 'Sky Galloping Gaia the Dragon Champion', '天翔之龙骑士盖亚', '天翔の竜騎士ガイア', 'Fusion Monster', 'Dragon', 'WIND', 7, 2600, 2100, '「暗黑骑士 盖亚」怪兽＋龙族怪兽 ①：这张卡只要在怪兽区域存在，卡名当作「龙骑士 盖亚」使用。 ②：这张卡特殊召唤成功的场合才能发动。从自己的卡组·墓地选1张「螺旋枪杀」加入手卡。 ③：这张卡向对方怪兽攻击宣言时才能发动。那只对方怪兽的表示形式变更。'),
(27813661, 'Sky Iris', '天空之虹彩', '天空の虹彩', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '「天空的虹彩」的②的效果1回合只能使用1次。 ①：只要这张卡在场地区域存在，自己的灵摆区域的「魔术师」卡、「娱乐伙伴」卡、「异色眼」卡不会成为对方的效果的对象。 ②：以这张卡以外的自己场上1张表侧表示的卡为对象才能发动。那张卡破坏，从卡组把1张「异色眼」卡加入手卡。'),
(15792576, 'Sky Scourge Cidhels', '天魔神 希德赫尔斯', '天魔神 シドヘルズ', 'Effect Monster', 'Fiend', 'EARTH', 6, 2200, 1600, '这张卡不能特殊召唤。 ①：这张卡上级召唤成功的场合才能发动。为这张卡的上级召唤而解放的怪兽的种族·属性的以下效果适用。 ●天使族·光属性：从卡组把1只天使族·光属性或者恶魔族·暗属性的怪兽加入手卡。 ●恶魔族·暗属性：从卡组把天使族·光属性和恶魔族·暗属性的怪兽各最多1只送去墓地。'),
(11458071, 'Sky Scourge Enrise', '天魔神 恩莱兹', '天魔神 エンライズ', 'Effect Monster', 'Fairy', 'LIGHT', 8, 2400, 1500, '这张卡不能通常召唤。把自己墓地的3只光属性·天使族怪兽和1只暗属性·恶魔族怪兽从游戏中除外的场合才能特殊召唤。可以把场上表侧表示存在的1只怪兽从游戏中除外。这个效果发动的场合，这个回合这张卡不能攻击。这个效果1回合只能使用1次。'),
(74841885, 'Sky Scourge Invicil', '天魔神 因维希尔', '天魔神 インヴィシル', 'Effect Monster', 'Fairy', 'EARTH', 6, 2200, 1600, '这张卡不能特殊召唤。为这张卡的上级召唤而解放的怪兽的种族和属性让这张卡得到以下效果。 ●天使族·光属性：只要这张卡在场上表侧表示存在，场上的魔法卡的效果无效。 ●恶魔族·暗属性：只要这张卡在场上表侧表示存在，场上的陷阱卡的效果无效。'),
(48453776, 'Sky Scourge Norleras', '天魔神 诺雷拉斯', '天魔神 ノーレラス', 'Effect Monster', 'Fiend', 'DARK', 8, 2400, 1500, '这张卡不能通常召唤。从自己墓地把1只天使族·光属性怪兽和3只恶魔族·暗属性怪兽除外的场合才能特殊召唤。 ①：支付1000基本分才能发动。双方的手卡·场上的卡全部送去墓地，自己从卡组抽1张。'),
(30532390, 'Sky Scout', '鸟人', 'バードマン', 'Normal Monster', 'Winged Beast', 'WIND', 4, 1800, 600, '以5马赫飞行的鸟人。他的目光比鹰还锐利。'),
(98462037, 'Sky Striker Ace - Azalea', '闪刀姬－阿萨蕾娅', '閃刀姫－アザレア', 'Link Monster', 'Machine', 'DARK', NULL, 1500, NULL, '光·暗属性怪兽2只 这张卡不用连接召唤不能特殊召唤，自己对「闪刀姬-阿泽莉娅」1回合只能有1次特殊召唤。 ①：这张卡特殊召唤的场合，以场上1张卡为对象才能发动。那张卡破坏。那之后，自己墓地的魔法卡是3张以下的场合，这张卡送去墓地。 ②：1回合1次，这张卡和对方怪兽进行战斗的伤害步骤开始时，从自己墓地把1张魔法卡除外才能发动。那只对方怪兽破坏。'),
(56741506, 'Sky Striker Ace - Azalea Temperance', '闪刀姬－阿萨蕾娅・律制', '閃刀姫－アザレア・テンペランス', 'Link Monster', 'Machine', 'DARK', NULL, 2500, NULL, '包含连接怪兽的怪兽2只以上 这张卡不用连接召唤不能从额外卡组特殊召唤。这个卡名的①的效果1回合只能使用1次。 ①：这张卡特殊召唤的场合，从自己的手卡·墓地把1张魔法卡除外，以对方场上1只攻击力2500以下的怪兽为对象才能发动。那只表侧表示怪兽当作装备魔法卡使用给这张卡装备。 ②：这张卡被战斗破坏时才能发动。从自己的手卡·墓地把这张卡以外的1只「闪刀」怪兽特殊召唤。'),
(63013339, 'Sky Striker Ace - Camellia', '闪刀姬－卡梅莉娅', '閃刀姫－カメリア', 'Link Monster', 'Machine', 'DARK', NULL, 1500, NULL, '效果怪兽2只 这张卡不用连接召唤不能从额外卡组特殊召唤，自己对「闪刀姬-卡米丽娅」1回合只能有1次特殊召唤。 ①：1回合1次，自己墓地的魔法卡是3张以下的场合才能发动。从卡组把1张「闪刀」卡送去墓地。 ②：这张卡被送去墓地的场合，以对方场上1只怪兽为对象才能发动。这张卡在对方场上特殊召唤，作为对象的怪兽送去墓地。这张卡的控制权在这个回合的结束阶段回归原本持有者。'),
(8491308, 'Sky Striker Ace - Hayate', '闪刀姬－飒', '閃刀姫－ハヤテ', 'Link Monster', 'Machine', 'WIND', NULL, 1500, NULL, '风属性以外的「闪刀姬」怪兽1只 自己对「闪刀姬-飒天」1回合只能有1次特殊召唤。 ①：这张卡可以直接攻击。 ②：这张卡进行战斗的伤害计算后才能发动。从卡组把1张「闪刀」卡送去墓地。'),
(63288573, 'Sky Striker Ace - Kagari', '闪刀姬－篝', '閃刀姫－カガリ', 'Link Monster', 'Machine', 'FIRE', NULL, 1500, NULL, '炎属性以外的「闪刀姬」怪兽1只 自己对「闪刀姬-燎里」1回合只能有1次特殊召唤。 ①：这张卡特殊召唤的场合，以自己墓地1张「闪刀」魔法卡为对象才能发动。那张卡加入手卡。 ②：这张卡的攻击力上升自己墓地的魔法卡数量×100。'),
(12421694, 'Sky Striker Ace - Kaina', '闪刀姬－腕', '閃刀姫－カイナ', 'Link Monster', 'Machine', 'EARTH', NULL, 1500, NULL, '地属性以外的「闪刀姬」怪兽1只 自己对「闪刀姬-魁奈」1回合只能有1次特殊召唤。 ①：这张卡特殊召唤成功的场合，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽直到对方回合结束时不能攻击。 ②：只要这张卡在怪兽区域存在，每次自己把「闪刀」魔法卡的效果发动，自己回复100基本分。'),
(26077387, 'Sky Striker Ace - Raye', '闪刀姬－零', '閃刀姫－レイ', 'Effect Monster', 'Warrior', 'DARK', 4, 1500, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方回合，把这张卡解放才能发动。从额外卡组把1只「闪刀姬」怪兽在额外怪兽区域特殊召唤。 ②：这张卡在墓地存在的状态，自己场上的「闪刀姬」连接怪兽因对方的效果从场上离开的场合或者被战斗破坏的场合才能发动。这张卡特殊召唤。'),
(37351133, 'Sky Striker Ace - Roze', '闪刀姬－萝杰', '閃刀姫－ロゼ', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1500, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：「闪刀姬-露世」以外的「闪刀姬」怪兽召唤·特殊召唤的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡在墓地存在的状态，额外怪兽区域的对方怪兽被战斗破坏的场合或者因自己的卡的效果从场上离开的场合才能发动。这张卡特殊召唤。那之后，可以把对方场上1只表侧表示怪兽的效果直到回合结束时无效。'),
(90673288, 'Sky Striker Ace - Shizuku', '闪刀姬－雫', '閃刀姫－シズク', 'Link Monster', 'Machine', 'WATER', NULL, 1500, NULL, '水属性以外的「闪刀姬」怪兽1只 自己对「闪刀姬-雫空」1回合只能有1次特殊召唤。 ①：对方场上的怪兽的攻击力·守备力下降自己墓地的魔法卡数量×100。 ②：这张卡特殊召唤的回合的结束阶段才能发动。同名卡不在自己墓地存在的1张「闪刀」魔法卡从卡组加入手卡。'),
(75147529, 'Sky Striker Ace - Zeke', '闪刀姬－泽克', '閃刀姫－ジーク', 'Link Monster', 'Machine', 'DARK', NULL, 1500, NULL, '包含「闪刀姬」怪兽的怪兽2只 这张卡不用连接召唤不能特殊召唤，自己对「闪刀姬-泽克」1回合只能有1次特殊召唤。 ①：这张卡连接召唤成功的场合，以场上1只表侧表示怪兽为对象才能发动。那只怪兽直到下次的对方结束阶段除外。 ②：1回合1次，以这张卡以外的自己场上1张卡为对象才能发动。这张卡的攻击力上升1000。那之后，作为对象的卡送去墓地。'),
(76072561, 'Sky Striker Ace = Zero', '闪刀姬＝零萝', '閃刀姫＝ゼロ', 'Link Monster', 'Machine', 'LIGHT', NULL, 2000, NULL, '「闪刀姬」怪兽2只 自己对「闪刀姬=零露」1回合只能有1次特殊召唤，这张卡不能作为连接素材。这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡特殊召唤的场合才能发动。从自己的卡组·墓地把1张「闪刀」魔法卡加入手卡。 ②：自己·对方回合，把这张卡解放才能发动。「闪刀姬-零衣」「闪刀姬-露世」各1只从自己的卡组·墓地特殊召唤。那之后，可以把场上1张卡破坏。'),
(52340445, 'Sky Striker Ace Token', '闪刀机－大黄蜂无人机', '閃刀機－ホーネットビット', 'Token', 'Warrior', NULL, NULL, NULL, NULL, NULL),
(50005218, 'Sky Striker Airspace - Area Zero', '闪刀空域－零域', '閃刀空域－エリアゼロ', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以这张卡以外的自己场上1张卡为对象才能发动。从自己卡组上面把3张卡翻开。可以从那之中选1张「闪刀」卡加入手卡。剩下的卡回到卡组。「闪刀」卡被翻开的场合，再把作为对象的卡送去墓地。 ②：这张卡被效果从场地区域送去墓地的场合才能发动。从卡组把1只「闪刀姬」怪兽特殊召唤。'),
(99550630, 'Sky Striker Maneuver - Afterburners!', '闪刀术式－烈火重燃', '閃刀術式－アフターバーナー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己的主要怪兽区域没有怪兽存在的场合，以场上1只表侧表示怪兽为对象才能发动。那只怪兽破坏。那之后，自己墓地有魔法卡3张以上存在的场合，可以选场上1张魔法·陷阱卡破坏。'),
(25955749, 'Sky Striker Maneuver - Jamming Waves!', '闪刀术式－干扰波', '閃刀術式－ジャミングウェーブ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己的主要怪兽区域没有怪兽存在的场合，以场上盖放的1张魔法·陷阱卡为对象才能发动。那张卡破坏。那之后，自己墓地有魔法卡3张以上存在的场合，可以选场上1只怪兽破坏。'),
(46271408, 'Sky Striker Maneuver - Scissors Cross', '闪刀术式－剪除交刃', '閃刀術式－シザーズクロス', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己的主要怪兽区域没有怪兽存在的场合，以自己墓地1只4星「闪刀姬」怪兽为对象才能发动。那只怪兽加入手卡。自己墓地有魔法卡3张以上存在的场合，也能不加入手卡特殊召唤。'),
(21623008, 'Sky Striker Maneuver - Vector Blast', '闪刀术式－矢量冲击波', '閃刀術式－ベクタードブラスト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己的主要怪兽区域没有怪兽存在的场合才能发动。从双方卡组上面把2张卡送去墓地。那之后，自己墓地有魔法卡3张以上存在的场合，可以让额外怪兽区域的对方怪兽全部回到持有者卡组。'),
(61151074, 'Sky Striker Mecha - Adhilsaber', '闪刀机－正义军刀', '閃刀機－アディルセイバー', 'Effect Monster', 'Machine', 'WIND', 7, 1500, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的战斗阶段，把这张卡从手卡丢弃，以场上1只「闪刀」怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升1500。 ②：这张卡在墓地存在的状态，怪兽特殊召唤的场合，以自己场上1只「闪刀」连接怪兽为对象才能发动。这张卡当作攻击力上升1500的装备魔法卡使用给那只怪兽装备。'),
(25733157, 'Sky Striker Mecha - Eagle Booster', '闪刀机－鹰式助推器', '閃刀機－イーグルブースター', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：自己的主要怪兽区域没有怪兽存在的场合，以场上1只表侧表示怪兽为对象才能发动。这个回合，那只表侧表示怪兽不受自身以外的卡的效果影响。自己墓地有魔法卡3张以上存在的场合，再在这个回合让那只怪兽不会被战斗破坏。'),
(52340444, 'Sky Striker Mecha - Hornet Drones', '闪刀机－大黄蜂无人机', '閃刀機－ホーネットビット', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：自己的主要怪兽区域没有怪兽存在的场合才能发动。在自己场上把1只「闪刀姬衍生物」（战士族·暗·1星·攻/守0）守备表示特殊召唤。这衍生物不能解放。自己墓地有魔法卡3张以上存在的场合，那衍生物的攻击力·守备力变成1500。'),
(51227866, 'Sky Striker Mecha - Shark Cannon', '闪刀机－鲨鱼加农炮', '閃刀機－シャークキャノン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：自己的主要怪兽区域没有怪兽存在的场合，以对方墓地1只怪兽为对象才能发动。那只怪兽除外。自己墓地有魔法卡3张以上存在的场合，可以不除外而把那只怪兽在自己场上特殊召唤。这个效果特殊召唤的怪兽不能攻击。'),
(98338152, 'Sky Striker Mecha - Widow Anchor', '闪刀机－黑寡妇锚', '閃刀機－ウィドウアンカー', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：自己的主要怪兽区域没有怪兽存在的场合，以场上1只效果怪兽为对象才能发动。那只怪兽的效果直到回合结束时无效。那之后，自己墓地有魔法卡3张以上存在的场合，可以把那只怪兽的控制权直到结束阶段得到。'),
(24010609, 'Sky Striker Mecha Modules - Multirole', '闪刀机关－多用途战机', '閃刀機関－マルチロール', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，以这张卡以外的自己场上1张卡为对象才能发动。这个回合，对方不能对应自己的魔法卡的发动把魔法·陷阱·怪兽的效果发动。并且，再把作为对象的卡送去墓地。 ②：自己·对方的结束阶段才能发动。选最多有这个回合这张卡表侧表示存在期间自己发动的「闪刀」魔法卡数量的自己墓地的「闪刀」魔法卡在自己场上盖放（同名卡最多1张）。这个效果盖放的卡从场上离开的场合除外。'),
(97616504, 'Sky Striker Mecharmory - Hercules Base', '闪刀机构－大力神基地', '閃刀機構－ハーキュリーベース', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '自己的主要怪兽区域没有怪兽存在的场合才能把这张卡发动。 ①：装备怪兽不能直接攻击，同1次的战斗阶段中最多2次可以向怪兽攻击。 ②：装备怪兽的攻击破坏怪兽的场合，若自己墓地有魔法卡3张以上存在则发动。自己从卡组抽1张。 ③：这张卡被效果从场上送去墓地的场合，以「闪刀机构-大力神基地」以外的自己墓地最多3张「闪刀」卡为对象才能发动。那些卡回到卡组。'),
(63166095, 'Sky Striker Mobilize - Engage!', '闪刀起动－交闪', '閃刀起動－エンゲージ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己的主要怪兽区域没有怪兽存在的场合才能发动。从卡组把「闪刀起动-交闪」以外的1张「闪刀」卡加入手卡。那之后，自己墓地有魔法卡3张以上存在的场合，自己可以抽1张。'),
(9726840, 'Sky Striker Mobilize - Linkage!', '闪刀启动－连闪', '閃刀起動－リンケージ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：自己的主要怪兽区域没有怪兽存在的场合才能发动。自己场上1张其他卡送去墓地，从额外卡组把1只「闪刀姬」怪兽在额外怪兽区域特殊召唤。自己的场上·墓地有光属性和暗属性的「闪刀姬」怪兽各存在的场合，这个效果特殊召唤的怪兽的攻击力上升1000。这张卡的发动后，直到回合结束时自己不是「闪刀姬」怪兽不能从额外卡组特殊召唤。'),
(34433770, 'Sky Striker Special Maneuver - Lemnisgate!', '闪刀亚式－双纽无限门', '閃刀亜式－レムニスゲート', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己墓地的「闪刀姬」怪兽和「闪刀」魔法卡各相同数量为对象才能发动。那些卡回到卡组。那之后，可以让回去的卡每3张最多1张的场上的卡回到手卡。 ②：这张卡在墓地存在的状态，自己场上有「闪刀」怪兽特殊召唤的场合，把这张卡除外才能发动。进行1只「闪刀姬」连接怪兽的连接召唤。'),
(12958920, 'Skyblaster Token', '幻铳士', '幻銃士', 'Token', 'Fiend', NULL, NULL, NULL, NULL, NULL),
(40522482, 'Skydive Scorcher', '摩天一击', 'スカイスクレイパー・シュート', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只「元素英雄」融合怪兽为对象才能发动。比那只怪兽攻击力高的对方场上的表侧表示怪兽全部破坏。那之后，给与对方这个效果破坏送去墓地的怪兽之内原本攻击力最高的怪兽的那个数值的伤害。自己的场地区域有「摩天楼」场地魔法卡存在的场合，给与对方的伤害变成这个效果破坏送去墓地的怪兽全部的原本攻击力的合计数值。'),
(3814632, 'Skypalace Gangaridai', '超巨大空中宫殿 冈加里迪亚', '超巨大空中宮殿ガンガリディア', 'XYZ Monster', 'Machine', 'WIND', 10, 3400, 3000, '10星怪兽×2 这个卡名的效果1回合只能使用1次，这个效果发动的回合，这张卡不能攻击。 ①：把这张卡1个超量素材取除，以对方场上1张卡为对象才能发动。那张对方的卡破坏，给与对方1000伤害。'),
(63035430, 'Skyscraper', '摩天楼', '摩天楼 －スカイスクレイパー－', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：「元素英雄」怪兽的攻击力只在向持有比自身的攻击力高的攻击力的怪兽攻击的伤害计算时上升1000。'),
(47596607, 'Skyscraper 2 - Hero City', '摩天楼2-英雄都市', '摩天楼２－ヒーローシティ', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '1回合1次，自己的主要阶段时，选择被战斗破坏送去自己墓地的1只名字带有「元素英雄」的怪兽才能发动。选择的怪兽从墓地特殊召唤。'),
(47349310, 'Skystarray', '天鬼食人蝠鲼', 'スカイオニヒトクイエイ', 'Effect Monster', 'Sea Serpent', 'WIND', 3, 600, 300, '这张卡可以直接攻击对方玩家。这张卡进行直接攻击的战斗阶段结束时，这张卡直到下次的自己的准备阶段时从游戏中除外。'),
(58058134, 'Slacker Magician', '内向尼特魔术师', 'シャイニート・マジシャン', 'XYZ Monster', 'Spellcaster', 'LIGHT', 1, 200, 2100, '1星怪兽×2 ①：这张卡1回合只有1次不会被战斗破坏。 ②：场上的这张卡为对象的魔法·陷阱·怪兽的效果发动时，把这张卡1个超量素材取除才能发动。那个发动无效并破坏。'),
(71344451, 'Slash Draw', '一击必杀！居合抽牌', '一撃必殺！居合いドロー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：丢弃1张手卡才能发动。把对方场上的卡数量的卡从自己卡组上面送去墓地，那之后自己从卡组抽1张，给双方确认。那是「一击必杀！居合抽卡」的场合，那张送去墓地，场上的卡全部破坏。那之后，给与对方这个效果破坏送去墓地的卡数量×2000伤害。不是的场合，自己选这个效果从卡组送去墓地的卡数量的自己墓地的卡回到卡组。'),
(78636495, 'Slate Warrior', '纽特', 'ニュート', 'Flip Effect Monster', 'Fiend', 'WIND', 4, 1900, 400, '①：这张卡反转的场合发动。这张卡的攻击力·守备力上升500。 ②：这张卡被战斗破坏的场合发动。让把这张卡破坏的怪兽的攻击力·守备力下降500。'),
(40200834, 'Sleeping Lion', '睡狮子', '眠れる獅子', 'Normal Monster', 'Beast', 'EARTH', 4, 700, 1700, '平时沉睡着的猛兽。一旦苏醒就使人招架不住。'),
(74659582, 'Sleipnir the Runick Mane', '神碑之鬣 斯雷普尼尔', '神碑の鬣スレイプニル', 'Fusion Monster', 'Beast', 'LIGHT', 9, 1500, 1500, '「神碑」怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段以及对方战斗阶段，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽和这张卡直到结束阶段除外。 ②：对方从卡组把卡加入手卡的场合才能发动。在自己场上把1只「神碑衍生物」（天使族·光·4星·攻/守1500）攻击表示特殊召唤。'),
(10000020, 'Slifer the Sky Dragon', '欧西里斯之天空龙', 'オシリスの天空竜', 'Effect Monster', 'Divine-Beast', 'DIVINE', 10, -1, -1, '这张卡通常召唤的场合，必须把3只解放作召唤。 ①：这张卡的召唤不会被无效化。 ②：在这张卡的召唤成功时双方不能把卡的效果发动。 ③：这张卡的攻击力·守备力上升自己手卡数量×1000。 ④：每次对方场上有怪兽攻击表示召唤·特殊召唤发动。那些怪兽的攻击力下降2000。变成0的场合那怪兽破坏。 ⑤：这张卡特殊召唤的场合，结束阶段发动。这张卡送去墓地。'),
(68638985, 'Slime Toad', '蛙形史莱姆', 'カエルスライム', 'Normal Monster', 'Aqua', 'WATER', 2, 700, 500, '蛙头形状的史莱姆。呱呱叫唱着难听的歌来攻击。'),
(21770261, 'Slime Token', '史莱姆增殖炉', 'スライム増殖炉', 'Token', 'Aqua', NULL, NULL, NULL, NULL, NULL),
(72885174, 'Slip of Fortune', '命运旅行', 'フォーチュン・スリップ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方怪兽的攻击宣言时才能发动。把1只对方怪兽的攻击无效，1只攻击对象怪兽直到下次的准备阶段时从游戏中除外。'),
(94484482, 'Slip Summon', '滑流召唤', 'スリップ・サモン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方对怪兽的召唤·反转召唤·特殊召唤成功时才能发动。从手卡把1只4星以下的怪兽表侧守备表示特殊召唤。这个效果特殊召唤的怪兽在结束阶段时回到持有者手卡。'),
(3797883, 'Slot Machine', '角子老虎机AM-7', 'スロットマシーンAM－７', 'Normal Monster', 'Machine', 'DARK', 7, 2000, 2300, '据说根据插件集齐的数量能力会发生变化的机器。'),
(10505300, 'Slower Swallow', '悠悠燕', 'スロワースワロー', 'Effect Monster', 'Winged Beast', 'WIND', 1, 100, 100, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：场上有相同等级的怪兽2只以上存在的场合，这张卡可以从手卡特殊召唤。 ②：把这张卡解放才能发动。下次的自己抽卡阶段的通常抽卡变成2张。'),
(84650463, 'Slushy', '冰沙怪', 'フラッピィ', 'Effect Monster', 'Aqua', 'WATER', 2, NULL, NULL, '这张卡召唤成功时，可以从卡组把1只「冰沙怪」送去墓地。此外，自己墓地的「冰沙怪」以及从游戏中除外的自己的「冰沙怪」的合计是3只的场合，把墓地的这张卡从游戏中除外才能发动。选择自己墓地1只海龙族·5星以上的怪兽特殊召唤。「冰沙怪」的这个效果1回合只能使用1次。'),
(22754505, 'Small Piece Golem', '小块石人', 'スモール・ピース・ゴーレム', 'Effect Monster', 'Rock', 'EARTH', 3, 1100, NULL, '自己场上有「大块石人」表侧表示存在的场合这张卡召唤·反转召唤·特殊召唤成功时，可以从自己卡组把1只「中块石人」特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(300302052, 'Small Roid Big City', NULL, NULL, 'Skill Card', 'Syrus Truesda', NULL, NULL, NULL, NULL, NULL),
(15967552, 'Small Scuffle', '小小的对抗', 'リトル・オポジション', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：指定相同纵列的没有使用的主要怪兽区域2处才能发动。自己让以下效果适用。那之后，对方可以让以下效果适用。 ●从自身的手卡·卡组选1只2星以下的怪兽在指定的自身的主要怪兽区域表侧攻击表示或里侧守备表示特殊召唤。'),
(89558743, 'Small World', '小世界', 'スモール・ワールド', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把手卡1只怪兽给对方观看。从卡组选种族·属性·等级·攻击力·守备力之内只有1个是和给人观看的怪兽相同的1只怪兽确认，从手卡给人观看的怪兽里侧除外。并且，再把种族·属性·等级·攻击力·守备力之内只有1个是和确认的怪兽相同的1只怪兽从卡组加入手卡，从卡组确认的怪兽里侧除外。'),
(97169186, 'Smashing Ground', '地碎', '地砕き', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方场上1只守备力最高的怪兽破坏。'),
(93396832, 'Smashing Horn', '角笛粉碎', '角笛砕き', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '要让怪兽的召唤·特殊召唤无效的怪兽的效果·陷阱卡发动时才能发动。那个发动无效并破坏。'),
(47870325, 'Smile Action', '笑容动作', 'スマイル・アクション', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：作为这张卡的发动时的效果处理，双方玩家各自可以从自己墓地选最多5张魔法卡里侧表示除外。 ②：怪兽的攻击宣言时发动。被攻击的玩家可以让以下效果适用。 ●从这张卡的效果除外的自己的卡之中随机选1张加入手卡。那之后，可以把那张卡丢弃让那次攻击无效。没丢弃的场合，这个回合，自己受到的战斗伤害变成2倍。'),
(16720314, 'Smile Potion', '笑容药水', 'スマイル・ポーション', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上没有怪兽存在，持有比原本攻击力高的攻击力的怪兽在对方场上存在的场合才能发动。自己从卡组抽2张。'),
(35259350, 'Smile Universe', '笑容宇宙', 'スマイル・ユニバース', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这张卡发动的回合，自己不能用这张卡的效果以外把怪兽召唤·特殊召唤，自己怪兽不能攻击。 ①：从自己的额外卡组把表侧表示的灵摆怪兽尽可能特殊召唤。这个效果特殊召唤的怪兽的效果无效化。那之后，对方基本分回复这个效果特殊召唤的怪兽的原本攻击力合计的数值。'),
(2099841, 'Smile World', '笑容世界', 'スマイル・ワールド', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：场上的全部怪兽的攻击力直到回合结束时上升场上的怪兽数量×100。'),
(63789924, 'Smoke Grenade of the Thief', '盗贼的烟雾弹', '盗人の煙玉', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '装备在怪兽上的这张卡被其他卡的效果破坏时，看对方手卡并选择1张丢弃。'),
(28427869, 'Smoke Mosquito', '卷烟蚊', 'スモーク・モスキート', 'Effect Monster', 'Insect', 'DARK', 1, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：对方怪兽的攻击要让自己受到战斗伤害的伤害计算时才能发动。这张卡从手卡特殊召唤，那次战斗发生的对自己的战斗伤害变成一半，那次伤害步骤结束后战斗阶段结束。 ②：以自己场上1只表侧表示怪兽为对象才能发动。这张卡的等级直到回合结束时变成和那只怪兽相同。'),
(80678380, 'Snake Deity''s Command', '蛇神的敕命', '蛇神の勅命', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '把手卡1张名字带有「蛇毒」的怪兽卡给对方观看发动。对方的魔法卡的发动和效果无效，并把那个破坏。'),
(596051, 'Snake Fang', '毒蛇之牙', '毒蛇の牙', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择场上表侧表示存在的1只怪兽发动。选择的怪兽的守备力直到结束阶段时下降500。'),
(17189677, 'Snake Rain', '蛇雨', 'スネーク・レイン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：丢弃1张手卡才能发动。从卡组把4只爬虫类族怪兽送去墓地。'),
(81791932, 'Snake Whistle', '蛇哨', 'スネーク・ホイッスル', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上存在的爬虫类族怪兽被破坏时才能发动。从自己卡组把1只4星以下的爬虫类族怪兽在自己场上特殊召唤。'),
(9674034, 'Snake-Eye Ash', '蛇眼・艾柯赛尔', 'スネークアイ・エクセル', 'Effect Monster', 'Pyro', 'FIRE', 1, 800, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把1只炎属性·1星怪兽加入手卡。 ②：把包含这张卡的自己场上2张表侧表示卡送去墓地才能发动。从手卡·卡组把「蛇眼梣树灵」以外的1只「蛇眼」怪兽特殊召唤。'),
(12058741, 'Snake-Eye Birch', '蛇眼・怀特巴棋', 'スネークアイ・ワイトバーチ', 'Effect Monster', 'Pyro', 'FIRE', 1, NULL, 2100, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己场上有炎属性怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：对方回合，把包含这张卡的自己场上2张表侧表示卡送去墓地才能发动。从手卡·卡组把「蛇眼桦树灵」以外的1只「蛇眼」怪兽特殊召唤。'),
(45663742, 'Snake-Eye Oak', '蛇眼・奥柯', 'スネークアイ・オーク', 'Effect Monster', 'Pyro', 'FIRE', 1, 900, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合，以自己的墓地·除外状态的1只炎属性·1星怪兽为对象才能发动。那只怪兽加入手卡或特殊召唤。 ②：把包含这张卡的自己场上2张表侧表示卡送去墓地才能发动。从手卡·卡组把「蛇眼橡树灵」以外的1只「蛇眼」怪兽特殊召唤。'),
(27260347, 'Snake-Eyes Diabellstar', '蛇眼大炎魔・迪亚贝尔斯塔', '蛇眼の大炎魔', 'Effect Monster', 'Spellcaster', 'FIRE', 8, 2800, 2600, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡和对方怪兽进行战斗的攻击宣言时才能发动。那只对方怪兽和这张卡各当作永续魔法卡使用在原本持有者的魔法与陷阱区域表侧表示放置。 ②：这张卡是当作永续魔法卡使用的场合，以「蛇眼大炎魔」以外的自己墓地1只炎属性怪兽为对象才能发动。那只怪兽当作永续魔法卡使用在原本持有者的魔法与陷阱区域表侧表示放置，这张卡特殊召唤。'),
(58071334, 'Snake-Eyes Doomed Dragon', '蛇眼原罪龙', '蛇眼の原罪龍', 'Fusion Monster', 'Dragon', 'FIRE', 8, 3000, 2500, '「蛇眼」怪兽＋幻想魔族怪兽 这张卡用融合召唤以及以下方法才能特殊召唤。 ●把自己的魔法与陷阱区域2张表侧表示的怪兽卡送去墓地的场合可以从额外卡组特殊召唤。这个卡名的效果1回合只能使用1次。 ①：这张卡特殊召唤的场合，以场上1只表侧表示怪兽为对象才能发动。那只怪兽当作永续魔法卡使用在原本持有者的魔法与陷阱区域表侧表示放置。'),
(48452496, 'Snake-Eyes Flamberge Dragon', '蛇眼炎龙', '蛇眼の炎龍', 'Effect Monster', 'Dragon', 'FIRE', 8, 3000, 2500, '这个卡名的①②③的效果1回合各能使用1次。 ①：以自己或对方的场上（表侧表示）·墓地1只怪兽为对象才能发动。那只怪兽当作永续魔法卡使用在原本持有者的魔法与陷阱区域表侧表示放置。 ②：对方回合，以场上1张当作永续魔法卡使用的怪兽卡为对象才能发动。那张卡在自己场上特殊召唤。 ③：这张卡从手卡·场上送去墓地的场合才能发动。从自己墓地把2只炎属性·1星怪兽特殊召唤。'),
(90241276, 'Snake-Eyes Poplar', '蛇眼炎燐', '蛇眼の炎燐', 'Effect Monster', 'Pyro', 'FIRE', 1, 700, 200, '这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡用抽卡以外的方法加入手卡的场合才能发动。这张卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。从卡组把1张「蛇眼」魔法·陷阱卡加入手卡。 ③：这张卡被送去墓地的场合，以自己墓地1只炎属性怪兽为对象才能发动。那只怪兽当作永续魔法卡使用在原本持有者的魔法与陷阱区域表侧表示放置。'),
(79415624, 'Snake-Eyes Vengeance Dragon', '蛇眼断罪龙', '蛇眼の断罪龍', 'Synchro Monster', 'Dragon', 'FIRE', 12, 3000, 2500, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段，以自己或对方的场上（表侧表示）·墓地1只怪兽为对象才能发动。那只怪兽当作永续魔法卡使用在原本持有者的魔法与陷阱区域表侧表示放置。下个回合，这张卡不能使用这个效果。 ②：自己·对方的战斗阶段，以场上1只怪兽和场上1张永续魔法卡为对象才能发动。那些卡破坏。'),
(29802344, 'Snakeyashi', '蛇椰树', 'スネーク・パーム', 'Normal Monster', 'Plant', 'EARTH', 4, 1000, 1200, '许多的蛇聚集在一起。一旦敌人靠近就分散进行攻击。'),
(75673220, 'Snapdragon', '龙口花', 'スナップドラゴン', 'Effect Monster', 'Plant', 'EARTH', 2, 300, 100, '这张卡被送去墓地时，对方手卡随机选择1张，直到结束阶段时表侧表示从游戏中除外。「龙口花」的效果1回合只能使用1次。'),
(45986603, 'Snatch Steal', '强夺', '強奪', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '可以给对方场上的怪兽装备。 ①：得到装备怪兽的控制权。 ②：对方准备阶段发动。对方回复1000基本分。'),
(25137581, 'Sneaky "C"', '潜伏的Z', '潜伏するG', 'Effect Monster', 'Insect', 'EARTH', 7, 1300, 2500, '这个卡名的①的效果1回合只能使用1次。 ①：对方对怪兽的特殊召唤成功时才能发动。这张卡从手卡里侧守备表示特殊召唤。这个效果特殊召唤的这张卡在这个回合的结束阶段变成表侧守备表示。 ②：这张卡在结束阶段反转的场合发动。场上的特殊召唤的怪兽全部破坏。'),
(27877771, 'Sniffer Dragon', '嗅探龙', 'スニッフィング・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 2, 800, 400, '这个卡名的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1只「嗅探龙」加入手卡。'),
(84290642, 'Snipe Hunter', '潜行狙击手', 'スナイプストーカー', 'Effect Monster', 'Fiend', 'DARK', 4, 1500, 600, '丢弃1张手卡，选择场上1张卡才能发动。掷1次骰子，1·6以外出现的场合，选择的卡破坏。'),
(39522887, 'Snopios, Shade of the Ghoti', '游魊之阴影 史诺匹奥斯', 'ゴーティスの陰影スノーピオス', 'Effect Monster', 'Fish', 'WATER', 6, 2100, NULL, '这个卡名的①②③的效果1回合各能使用1次。 ①：自己·对方的主要阶段，从自己的手卡·墓地把2只鱼族怪兽除外才能发动。这张卡从手卡特殊召唤。 ②：这张卡特殊召唤的场合，以场上1张表侧表示卡为对象才能发动。那张卡从场上离开的场合除外。 ③：这张卡被除外的场合，从自己墓地把1只鱼族怪兽除外才能发动。这张卡加入手卡。'),
(3070049, 'Snow Dragon', '雪龙', 'スノー・ドラゴン', 'Effect Monster', 'Dragon', 'WATER', 4, 1400, 900, '这张卡被战斗或者卡的效果破坏送去墓地时，给场上表侧表示存在的全部怪兽放置1个冰指示物。'),
(24731453, 'Snow Plow Hustle Rustle', '除雪机关车 扫雪冲锋', '除雪機関車ハッスル・ラッセル', 'Effect Monster', 'Machine', 'EARTH', 10, 2500, 3000, '①：自己的魔法与陷阱区域有卡存在的场合，对方怪兽的直接攻击宣言时才能发动。这张卡从手卡特殊召唤。那之后，自己的魔法与陷阱区域的卡全部破坏，给与对方破坏数量×200伤害。 ②：只要这张卡在怪兽区域存在，自己不是机械族怪兽不能特殊召唤。');